def average(values):
    if not values:
        return None
    return sum(values) / len(values)

result = average([2, 4, 6])
print(result)
assert result == 4
assert average([]) is None

class Cart:
    def __init__(self):
        self.total = 0
    def add(self, price):
        if price < 0:
            raise ValueError("Отрицательная цена")
        self.total += price

a, b = Cart(), Cart()
a.add(100)
a.add(250)
print(a.total, b.total)
